namespace api;

// weekly working schedule sent from the frontend when a user is created.
// times come as "HH:mm" (e.g. "08:00"), a day off has both start and end = null.
// id, user_id and effective_from are not here: id is generated by the db,
// user_id and effective_from (= user's start date) are set on the backend
public class ScheduleDTO
{
    public TimeOnly? monday_start { get; set; }
    public TimeOnly? monday_end { get; set; }
    public TimeOnly? tuesday_start { get; set; }
    public TimeOnly? tuesday_end { get; set; }
    public TimeOnly? wednesday_start { get; set; }
    public TimeOnly? wednesday_end { get; set; }
    public TimeOnly? thursday_start { get; set; }
    public TimeOnly? thursday_end { get; set; }
    public TimeOnly? friday_start { get; set; }
    public TimeOnly? friday_end { get; set; }

    public ScheduleDTO()
    {
    }

    // returns null if the schedule is valid, otherwise the error message
    public string? validate()
    {
        (string name, TimeOnly? start, TimeOnly? end)[] days =
        {
            ("Monday", monday_start, monday_end),
            ("Tuesday", tuesday_start, tuesday_end),
            ("Wednesday", wednesday_start, wednesday_end),
            ("Thursday", thursday_start, thursday_end),
            ("Friday", friday_start, friday_end)
        };

        bool has_working_day = false;
        foreach (var (name, start, end) in days)
        {
            // day off
            if (start == null && end == null)
            {
                continue;
            }

            if (start == null || end == null)
            {
                return name + ": both start and end time must be set, or none of them for a day off";
            }

            if (end <= start)
            {
                return name + ": end time must be after start time";
            }

            has_working_day = true;
        }

        if (!has_working_day)
        {
            return "schedule must have at least one working day";
        }

        return null;
    }

    public be.Schedule to_schedule()
    {
        return new be.Schedule
        {
            monday_start = monday_start, monday_end = monday_end,
            tuesday_start = tuesday_start, tuesday_end = tuesday_end,
            wednesday_start = wednesday_start, wednesday_end = wednesday_end,
            thursday_start = thursday_start, thursday_end = thursday_end,
            friday_start = friday_start, friday_end = friday_end
        };
    }
}
